    id: 'blog-youtube-algorithm-optimization-2026',
    title: 'YouTube Algorithm Optimization: The Master Playbook to Dominate Search and Suggested Videos in 2026',
    slug: 'youtube-algorithm-optimization-playbook-2026',
    category: 'YouTube Strategy',
